package com.hmdp.ai.runtime.knowledge.chunking;
import com.hmdp.ai.domain.knowledge.ChunkFragment;import com.hmdp.ai.domain.knowledge.ChunkingPolicy;import com.hmdp.ai.domain.knowledge.parsing.ParsedDocument;import org.springframework.stereotype.Component;import java.util.List;
@Component public class ParentChildChunkingStrategy implements ChunkingStrategy {private final HeadingAwareChunkingStrategy delegate;public ParentChildChunkingStrategy(HeadingAwareChunkingStrategy delegate){this.delegate=delegate;}public String code(){return "PARENT_CHILD";}public List<ChunkFragment> chunk(ParsedDocument d,ChunkingPolicy p){ChunkingPolicy child=new ChunkingPolicy("HEADING_AWARE",Math.max(p.getMinChars(),p.getMaxChars()/2),Math.min(p.getMinChars(),Math.max(1,p.getMaxChars()/2)),Math.min(p.getOverlapChars(),Math.max(0,p.getMaxChars()/4)),p.isPreserveHeading(),true,p.getTableStrategy(),p.isSemanticBoundaryEnabled());return delegate.chunk(d,child);}}
